    zones: {
      INSIDE_DHAKA: { id, delivery_charge, weight_step_kg, cod_percentage, ... },
      OUTSIDE_DHAKA: { id: null, delivery_charge: 0, ... },  // 0-fill
      SUB_DHAKA: { ... }
    }
  }
]
```

