  INSIDE_DHAKA: {
    PARTIAL_DELIVERY: { return_delivery_charge, return_weight_charge_per_kg, return_cod_percentage, ... },
    EXCHANGE: { ... },
    RETURNED: { ... },
    PAID_RETURN: { ... }
  },
  OUTSIDE_DHAKA: { ... },
  SUB_DHAKA: { ... }
}
